css:
.avatar-base {
  width: 90px; height: 90px; border-radius: 50%;
  background: var(--c-yellow); border: 3px solid #0f172a;
  position: relative; display: flex; align-items: center; justify-content: center;
}
.anim-engine .char-neutral { animation: neutralFloat 3s ease-in-out infinite; }
.eyes-pair { display: flex; gap: 24px; margin-top: -12px; }
.eye-dot { width: 9px; height: 12px; background: #0f172a; border-radius: 50%; }
.anim-engine .eye-blink { animation: eyeBlink 3.5s infinite; }
.neutral-mouth { position: absolute; bottom: 22px; width: 22px; height: 4px; background: #0f172a; border-radius: 2px; }
@keyframes eyeBlink { 0%, 94%, 100% { transform: scaleY(1); } 97% { transform: scaleY(0.1); } }
@keyframes neutralFloat { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }

.anim-engine .char-happy { animation: happyBounce 0.8s var(--ease-elastic) infinite alternate; }
.happy-eye { width: 14px; height: 8px; border: 3px solid #0f172a; border-bottom: none; border-radius: 14px 14px 0 0; }
.happy-mouth {
  position: absolute; bottom: 16px; width: 34px; height: 18px;
  background: #0f172a; border-radius: 0 0 34px 34px; overflow: hidden;
}
.happy-tongue { position: absolute; bottom: -3px; left: 8px; width: 18px; height: 12px; background: var(--c-pink); border-radius: 50%; }
@keyframes happyBounce { 0% { transform: translateY(0) scale(1); } 100% { transform: translateY(-8px) scale(1.05); } }

.thinking-container { position: relative; }
.thought-icon {
  position: absolute; top: -24px; right: -20px;
  font-weight: 900; font-size: 24px; color: var(--c-neon-blue); opacity: 0;
}
.anim-engine .thought-icon { animation: thoughtPop 2s ease-in-out infinite; }
.eye-think { width: 9px; height: 9px; background: #0f172a; border-radius: 50%; transform: translate(3px, -4px); }
.think-mouth { position: absolute; bottom: 22px; right: 26px; width: 10px; height: 10px; border: 3px solid #0f172a; border-radius: 50%; }
@keyframes thoughtPop { 0%, 100% { opacity: 0; transform: translateY(4px) scale(0.8); } 50% { opacity: 1; transform: translateY(-6px) scale(1.15); } }

.anim-engine .char-angry { animation: angryRage 0.6s ease-in-out infinite alternate; }
.angry-brow { position: absolute; width: 14px; height: 3px; background: #0f172a; top: 22px; }
.angry-brow.left { left: 20px; transform: rotate(26deg); }
.angry-brow.right { right: 20px; transform: rotate(-26deg); }
.angry-mouth { position: absolute; bottom: 18px; width: 24px; height: 7px; background: #0f172a; border-radius: 8px 8px 2px 2px; }
@keyframes angryRage {
  0% { background: #f87171; transform: translate(-2px, 1px) rotate(-1deg); }
  100% { background: var(--c-red); transform: translate(2px, -1px) rotate(1deg); }
}

.curse-wrapper { position: relative; }
.curse-badge {
  position: absolute; top: -32px; left: -10px; background: #000;
  color: var(--c-pink); border: 1px solid var(--border-color);
  padding: 3px 8px; border-radius: 5px; font-weight: 900; font-size: 13px;
  font-family: monospace; white-space: nowrap; opacity: 0;
}
.anim-engine .curse-badge { animation: curseGlitch 0.4s steps(2) infinite; }
.anim-engine .char-screaming { background: #fb7185; animation: screamShake 0.12s infinite; }
.scream-mouth {
  position: absolute; bottom: 10px; width: 30px; height: 38px;
  background: #0f172a; border-radius: 15px; border: 3px solid #fff;
}
@keyframes screamShake {
  0% { transform: translate(-3px, 2px) rotate(-2deg); }
  50% { transform: translate(3px, -2px) rotate(2deg); }
  100% { transform: translate(-1px, -2px) rotate(0deg); }
}
@keyframes curseGlitch {
  0% { opacity: 0; transform: scale(0.9) rotate(-3deg); }
  50% { opacity: 1; transform: scale(1.1) rotate(3deg); }
  100% { opacity: 1; transform: scale(1) rotate(0deg); }
}

.sleepy-z {
  position: absolute; top: -15px; right: -10px;
  font-family: monospace; font-weight: bold; font-size: 16px; color: var(--c-purple); opacity: 0;
}
.anim-engine .sleepy-z.z1 { animation: floatZ 2s infinite 0s; }
.anim-engine .sleepy-z.z2 { animation: floatZ 2s infinite 0.7s; }
.sleepy-line-eye { width: 14px; height: 3px; background: #0f172a; border-radius: 2px; }
.sleepy-mouth {
  position: absolute; bottom: 20px; width: 12px; height: 12px;
  background: #0f172a; border-radius: 50%;
}
@keyframes floatZ {
  0% { opacity: 0; transform: translate(0, 0) scale(0.6); }
  50% { opacity: 1; }
  100% { opacity: 0; transform: translate(20px, -24px) scale(1.2); }
}

.server-chassis {
  width: 100%; max-width: 270px; background: #0a0e17;
  border: 2px solid #283347; border-radius: 8px; padding: 12px; display: flex; flex-direction: column; gap: 8px;
}
.server-row { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #1a2233; padding-bottom: 6px; }
.led-strip { display: flex; gap: 6px; }
.led-pin { width: 8px; height: 8px; border-radius: 50%; background: #1e293b; }
.led-power { background: var(--c-green); box-shadow: 0 0 6px var(--c-green); }
.anim-engine .led-io { animation: ledFlicker 0.22s infinite alternate; }
.anim-engine .led-net { animation: ledFlicker 0.15s infinite steps(2); }
.linux-terminal {
  background: #000; padding: 6px 8px; border-radius: 4px;
  font-family: monospace; font-size: 10px; color: #cbd5e1; line-height: 1.4;
}
.anim-engine .term-blink { animation: termBlink 0.8s infinite; }
@keyframes ledFlicker {
  0%, 100% { background: #1e293b; box-shadow: none; }
  50% { background: var(--c-yellow); box-shadow: 0 0 8px var(--c-yellow); }
}
@keyframes termBlink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }

.car-scene { width: 100%; height: 120px; display: flex; flex-direction: column; align-items: center; justify-content: center; overflow: hidden; }
.car-body-wrap { position: relative; width: 140px; height: 44px; }
.anim-engine .car-body-wrap { animation: carSuspension 0.4s ease-in-out infinite alternate; }
.car-svg { width: 100%; height: 100%; fill: var(--c-pink); }
.car-wheel {
  position: absolute; bottom: -8px; width: 22px; height: 22px;
  background: #1e293b; border: 3px dashed var(--c-neon-blue); border-radius: 50%;
}
.car-wheel.rear { left: 18px; }
.car-wheel.front { right: 18px; }
.anim-engine .car-wheel { animation: spinWheel 0.5s linear infinite; }
.car-road {
  width: 100%; height: 2px;
  background: repeating-linear-gradient(90deg, var(--c-neon-blue) 0px, var(--c-neon-blue) 15px, transparent 15px, transparent 35px);
  margin-top: 8px;
}
.anim-engine .car-road { animation: roadScroll 0.4s linear infinite; }
@keyframes carSuspension { 0% { transform: translateY(0); } 100% { transform: translateY(-2px) rotate(0.6deg); } }
@keyframes spinWheel { 100% { transform: rotate(360deg); } }
@keyframes roadScroll { from { background-position: 0 0; } to { background-position: -35px 0; } }

.analog-clock {
  width: 110px; height: 110px; border-radius: 50%;
  border: 3px solid var(--border-color); background: #0c1017;
  position: relative; box-shadow: inset 0 0 10px rgba(0,0,0,0.6);
}
.clock-center-pin {
  width: 8px; height: 8px; background: var(--c-neon-blue); border-radius: 50%;
  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); z-index: 5;
}
.clock-hand { position: absolute; bottom: 50%; left: 50%; transform-origin: bottom center; border-radius: 4px; }
.hand-h { width: 3px; height: 28px; background: #fff; }
.hand-m { width: 2px; height: 38px; background: var(--text-dim); }
.hand-s { width: 1.5px; height: 44px; background: var(--c-red); }
.anim-engine .hand-h { animation: handSpin 24s linear infinite; }
.anim-engine .hand-m { animation: handSpin 6s linear infinite; }
.anim-engine .hand-s { animation: handSpin 2s steps(60) infinite; }
@keyframes handSpin {
  from { transform: translateX(-50%) rotate(0deg); }
  to { transform: translateX(-50%) rotate(360deg); }
}

.tacho-wrap { position: relative; width: 120px; height: 75px; display: flex; justify-content: center; overflow: hidden; }
.tacho-svg { width: 120px; height: 120px; transform: rotate(-90deg); }
.tacho-bg { fill: none; stroke: rgba(255,255,255,0.08); stroke-width: 8; stroke-dasharray: 188; stroke-dashoffset: 62; }
.tacho-progress {
  fill: none; stroke: var(--c-neon-blue); stroke-width: 8; stroke-linecap: round;
  stroke-dasharray: 188; stroke-dashoffset: 188;
}
.anim-engine .tacho-progress { animation: tachoFill 1.8s var(--ease-cinematic) infinite alternate; }
.anim-engine .tacho-needle { animation: needleSweep 1.8s var(--ease-cinematic) infinite alternate; }
.tacho-needle {
  position: absolute; bottom: 0; width: 3px; height: 50px; background: var(--c-pink);
  transform-origin: bottom center; transform: rotate(-70deg);
}
@keyframes tachoFill { to { stroke-dashoffset: 75; } }
@keyframes needleSweep { to { transform: rotate(50deg); } }

.bell-wrap { position: relative; width: 60px; height: 60px; display: grid; place-items: center; }
.bell-svg { width: 44px; height: 44px; fill: none; stroke: var(--text-main); stroke-width: 2; transform-origin: top center; }
.bell-badge {
  position: absolute; top: 2px; right: 6px; width: 14px; height: 14px;
  background: var(--c-pink); border-radius: 50%; border: 2px solid var(--card-bg);
}
.anim-engine .bell-svg { animation: bellRinging 1.4s ease-in-out infinite; }
.anim-engine .bell-badge { animation: badgePop 1.4s var(--ease-elastic) infinite; }
@keyframes bellRinging {
  0%, 100% { transform: rotate(0); }
  10%, 30% { transform: rotate(18deg); }
  20%, 40% { transform: rotate(-18deg); }
  50% { transform: rotate(0); }
}
@keyframes badgePop { 0%, 50% { transform: scale(1); } 60% { transform: scale(1.4); } 70% { transform: scale(1); } }

.stage-box { position: relative; width: 100%; height: 150px; border-radius: 8px; overflow: hidden; }
.curtain-curt {
  position: absolute; inset: 0; background: var(--c-pink); z-index: 2;
}
.anim-engine .curtain-curt { animation: curtainMotion 1.4s var(--ease-cinematic) forwards; }
.curtain-media {
  width: 100%; height: 100%; background: linear-gradient(135deg, #1e3a8a, #9333ea);
  display: grid; place-items: center; font-weight: bold; font-family: monospace;
}
.anim-engine .curtain-media { animation: zoomReveal 1.4s var(--ease-cinematic) forwards; }
@keyframes curtainMotion {
  0% { transform: scaleX(0); transform-origin: left; }
  45% { transform: scaleX(1); transform-origin: left; }
  55% { transform: scaleX(1); transform-origin: right; }
  100% { transform: scaleX(0); transform-origin: right; }
}
@keyframes zoomReveal {
  0%, 45% { opacity: 0; transform: scale(1.15); }
  50% { opacity: 1; }
  100% { opacity: 1; transform: scale(1); }
}

.diag-wrap { position: relative; width: 100%; height: 150px; border-radius: 8px; overflow: hidden; }
.diag-part {
  position: absolute; inset: 0; display: grid; place-items: center;
  font-weight: 800; font-family: monospace; background: linear-gradient(135deg, #059669, #0284c7);
}
.anim-engine .diag-p1 {
  clip-path: polygon(0 0, 100% 0, 0 100%);
  animation: diagInTop 1s var(--ease-cinematic) forwards;
}
.anim-engine .diag-p2 {
  clip-path: polygon(100% 0, 100% 100%, 0 100%);
  animation: diagInBtm 1s var(--ease-cinematic) forwards;
}
@keyframes diagInTop {
  from { transform: translate(-30%, -30%); opacity: 0; }
  to { transform: translate(0, 0); opacity: 1; }
}
@keyframes diagInBtm {
  from { transform: translate(30%, 30%); opacity: 0; }
  to { transform: translate(0, 0); opacity: 1; }
}

.iris-frame { width: 100%; height: 150px; border-radius: 8px; overflow: hidden; background: #000; }
.iris-fill {
  width: 100%; height: 100%; background: linear-gradient(135deg, #f59e0b, #ef4444);
  display: grid; place-items: center; font-weight: 800; font-family: monospace;
}
.anim-engine .iris-fill { animation: irisScale 1.4s var(--ease-cinematic) forwards; }
@keyframes irisScale {
  0% { clip-path: circle(0% at 50% 50%); transform: scale(1.2); }
  100% { clip-path: circle(75% at 50% 50%); transform: scale(1); }
}

.chart-frame {
  width: 220px; height: 110px; display: flex; align-items: flex-end;
  justify-content: space-between; border-bottom: 2px solid var(--border-color);
  border-left: 2px solid var(--border-color); position: relative; padding-left: 8px;
}
.metric-bar { width: 22px; background: var(--c-purple); border-radius: 3px 3px 0 0; transform-origin: bottom; transform: scaleY(0); }
.anim-engine .metric-bar:nth-child(1) { height: 40%; animation: barRise 1s var(--ease-cinematic) 0.1s forwards; }
.anim-engine .metric-bar:nth-child(2) { height: 75%; animation: barRise 1s var(--ease-cinematic) 0.25s forwards; }
.anim-engine .metric-bar:nth-child(3) { height: 55%; animation: barRise 1s var(--ease-cinematic) 0.4s forwards; }
.anim-engine .metric-bar:nth-child(4) { height: 95%; animation: barRise 1s var(--ease-cinematic) 0.55s forwards; }
.chart-overlay-svg { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.chart-trendline { fill: none; stroke: var(--c-neon-blue); stroke-width: 3; stroke-dasharray: 300; stroke-dashoffset: 300; }
.anim-engine .chart-trendline { animation: lineTrace 1.6s var(--ease-cinematic) 0.3s forwards; }
@keyframes barRise { to { transform: scaleY(1); } }
@keyframes lineTrace { to { stroke-dashoffset: 0; } }

.radial-loader-svg { width: 75px; height: 75px; transform: rotate(-90deg); }
.radial-spin {
  fill: none; stroke: var(--c-neon-blue); stroke-width: 6; stroke-linecap: round;
  stroke-dasharray: 220; stroke-dashoffset: 220; filter: drop-shadow(0 0 6px var(--c-neon-blue));
}
.anim-engine .radial-spin { animation: spinCycle 2s cubic-bezier(0.4, 0, 0.2, 1) infinite; }
@keyframes spinCycle {
  0% { stroke-dashoffset: 220; transform: rotate(0deg); transform-origin: 50% 50%; }
  50% { stroke-dashoffset: 50; transform: rotate(180deg); transform-origin: 50% 50%; }
  100% { stroke-dashoffset: 220; transform: rotate(720deg); transform-origin: 50% 50%; }
}

.bar-track { width: 85%; height: 10px; background: rgba(255,255,255,0.08); border-radius: 99px; overflow: hidden; }
.bar-lead {
  height: 100%; width: 100%;
  background: linear-gradient(90deg, var(--c-neon-blue), var(--c-pink), var(--c-yellow));
  background-size: 200% 100%; transform-origin: left;
}
.anim-engine .bar-lead { animation: barFill 2s var(--ease-cinematic) infinite, shimmerSlide 1.5s linear infinite; }
@keyframes barFill { 0% { transform: scaleX(0); } 100% { transform: scaleX(1); } }
@keyframes shimmerSlide { 0% { background-position: 100% 0; } 100% { background-position: -100% 0; } }
